-- MHP-DEALDESK-001 isolated migration119 proof. Caller rolls the entire transaction back.
-- Synthetic example.invalid identities only; no provider calls or emails.
SET LOCAL ROLE r72_owner;
DO $proof$
DECLARE ua uuid:=gen_random_uuid();ub uuid:=gen_random_uuid();wa uuid;wb uuid;owner_id uuid;owner_ws uuid;
 emaila text:='mhp-desk-a-'||gen_random_uuid()::text||'@example.invalid';emailb text:='mhp-desk-b-'||gen_random_uuid()::text||'@example.invalid';
 desk uuid;course uuid;purchase uuid:=gen_random_uuid();manual_id uuid:=gen_random_uuid();course_id uuid:=gen_random_uuid();
 ta bytea:=decode(repeat('1191',16),'hex');tb bytea:=decode(repeat('1192',16),'hex');tp bytea:=decode(repeat('1193',16),'hex');
 owner_token bytea:=decode(repeat('1194',16),'hex');owner_auth bytea:=decode(repeat('1195',16),'hex');
 cmd uuid:=gen_random_uuid();archive_cmd uuid:=gen_random_uuid();verdict_cmd uuid:=gen_random_uuid();review_cmd uuid:=gen_random_uuid();
 f1 uuid;f2 uuid;f3 uuid;f4 uuid;v1 uuid;v2 uuid;again uuid;denied boolean;value jsonb;a jsonb;stamp timestamptz:=clock_timestamp();checks integer:=0;
 calc jsonb:='{"calculator":"brrr","version":"proof-v1","source":"isolated-synthetic","inputs":{"purchasePrice":100000},"results":[],"status":"calculated","notes":[]}'::jsonb;
 answers jsonb:='{"experience":"First purchase","budget":"GBP 50000","weeklyTime":"Six hours","areas":"Manchester","goals":"One rental","questions":"Which lane fits?"}'::jsonb;
BEGIN
 IF app_private.mhp_five_working_days('2026-10-23T12:00:00Z')<>'2026-10-30T13:00:00Z'::timestamptz THEN RAISE EXCEPTION 'Desk proof: five weekdays / London DST'; END IF;checks:=checks+1;
 SELECT id INTO desk FROM app.products WHERE sku='mhp_deal_desk';SELECT id INTO course FROM app.products WHERE sku='mhp_course';
 IF NOT EXISTS(SELECT 1 FROM app.products WHERE id=desk AND active AND price_pence=4700 AND refund_days=14) THEN RAISE EXCEPTION 'Desk proof: catalogue'; END IF;checks:=checks+1;
 INSERT INTO app.users(id,email,display_name,status,email_verified_at) VALUES(ua,emaila,'Synthetic Desk A','active',stamp),(ub,emailb,'Synthetic Desk B','active',stamp);
 INSERT INTO app.purchases(id,organization_id,account_id,product_id,stripe_account_id,stripe_session_id,stripe_customer_id,buyer_email,livemode,status,first_paid_at,last_snapshot_at)
 VALUES(purchase,'ba41b1a4-9752-4dbf-8312-d04a0f03d0b8',ua,desk,'acct_DeskProof','cs_DeskProof119','cus_DeskProof119',emaila,false,'paid',stamp-interval '1 day',stamp);
 SET LOCAL ROLE r72_mhp_commerce_definer;
 PERFORM app_private.mhp_refresh_entitlement(purchase);PERFORM app_private.mhp_refresh_entitlement(purchase);
 SET LOCAL ROLE r72_owner;
 IF (SELECT count(*) FROM app.entitlements WHERE purchase_id=purchase)<>1 OR (SELECT count(*) FROM app.mhp_verdict_requests WHERE purchase_id=purchase)<>1 THEN RAISE EXCEPTION 'Desk proof: purchase projection replay'; END IF;checks:=checks+1;
 IF NOT EXISTS(SELECT 1 FROM app.entitlements WHERE purchase_id=purchase AND ends_at IS NULL AND crm_write_ends_at=stamp+interval '29 days') THEN RAISE EXCEPTION 'Desk proof: independent permanent/read and30daywrite'; END IF;checks:=checks+1;
 INSERT INTO app.entitlements(id,account_id,product_id,grants,starts_at,source,source_reference)
 SELECT manual_id,ub,id,grants,stamp-interval '1 hour','manual','isolated-desk-proof' FROM app.products WHERE id=desk;
 SET LOCAL ROLE r72_mhp_auth_definer;
 wa:=app_private.ensure_mhp_member_workspace(ua);wb:=app_private.ensure_mhp_member_workspace(ub);
 SET LOCAL ROLE r72_owner;
 INSERT INTO app.user_sessions(token_hash,csrf_secret_hash,user_id,selected_workspace_id,expires_at,product_audience)
 VALUES(ta,ta,ua,wa,stamp+interval '1 hour','martin_howard_property'),(tb,tb,ub,wb,stamp+interval '1 hour','martin_howard_property'),(tp,tp,ua,wa,stamp+interval '1 hour','property_predator_growth');
 SET LOCAL ROLE r72_web;
 value:=app_private.mhp_desk_snapshot(ta,NULL);a:=value->'access';
 IF NOT(a->>'calculators')::boolean OR NOT(a->>'crm')::boolean OR (a->>'readOnly')::boolean OR (a->>'emailWritable')::boolean OR (a->>'leadrelay')::boolean OR value->>'fileLimit'<>'3' THEN RAISE EXCEPTION 'Desk proof: paid feature mapping'; END IF;checks:=checks+1;
 denied:=false;BEGIN PERFORM app_private.mhp_desk_snapshot(tp,NULL);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: PP token admitted'; END IF;checks:=checks+1;
 denied:=false;BEGIN PERFORM id FROM app.deal_files;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: runtime direct table read'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_identity_command;
 f1:=app_private.mhp_save_deal_file(ta,cmd,NULL,NULL,'First deal','{"address":"1 Synthetic Road","notes":"Fixture"}','brrr',calc->'inputs',calc,'proof-v1');
 again:=app_private.mhp_save_deal_file(ta,cmd,NULL,NULL,'First deal','{"address":"1 Synthetic Road","notes":"Fixture"}','brrr',calc->'inputs',calc,'proof-v1');
 IF f1<>again THEN RAISE EXCEPTION 'Desk proof: file create replay'; END IF;checks:=checks+1;
 denied:=false;BEGIN PERFORM app_private.mhp_save_deal_file(ta,cmd,NULL,NULL,'Changed','{}','brrr',calc->'inputs',calc,'proof-v1');EXCEPTION WHEN serialization_failure THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: changed command replay'; END IF;checks:=checks+1;
 f2:=app_private.mhp_save_deal_file(ta,gen_random_uuid(),NULL,NULL,'Second deal','{}','brrr',calc->'inputs',calc,'proof-v1');
 f3:=app_private.mhp_save_deal_file(ta,gen_random_uuid(),NULL,NULL,'Third deal','{}','brrr',calc->'inputs',calc,'proof-v1');
 PERFORM app_private.mhp_archive_deal_file(ta,archive_cmd,f1,1,true);PERFORM app_private.mhp_archive_deal_file(ta,archive_cmd,f1,1,true);
 denied:=false;BEGIN PERFORM app_private.mhp_save_deal_file(ta,gen_random_uuid(),NULL,NULL,'Fourth deal','{}','brrr',calc->'inputs',calc,'proof-v1');EXCEPTION WHEN program_limit_exceeded THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: archive released lifetime slot'; END IF;checks:=checks+1;
 denied:=false;BEGIN PERFORM app_private.mhp_save_deal_file(tb,gen_random_uuid(),f2,1,'Foreign file','{}','brrr',calc->'inputs',calc,'proof-v1');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: foreign member changed file'; END IF;checks:=checks+1;
 PERFORM app_private.mhp_save_deal_file(ta,gen_random_uuid(),f2,1,'Second deal revised','{}','brrr',calc->'inputs',calc,'proof-v1');
 denied:=false;BEGIN PERFORM app_private.mhp_archive_deal_file(ta,gen_random_uuid(),f2,1,true);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: stale version accepted'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_web;
 value:=app_private.mhp_desk_snapshot(tb,f1);
 IF value->'selected'<>'null'::jsonb OR jsonb_array_length(value->'files')<>0 THEN RAISE EXCEPTION 'Desk proof: foreign file disclosed'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_owner;
 denied:=false;BEGIN DELETE FROM app.deal_files WHERE id=f1;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: deleting reopens lifetime slot'; END IF;checks:=checks+1;
 UPDATE app.entitlements SET crm_write_ends_at=stamp-interval '1 hour' WHERE purchase_id=purchase;
 SET LOCAL ROLE r72_web;
 value:=app_private.mhp_desk_snapshot(ta,f1);a:=value->'access';
 IF NOT(a->>'calculators')::boolean OR NOT(a->>'readOnly')::boolean OR (a->>'enquirySite')::boolean OR jsonb_array_length(value->'files')<>3 OR value->'selected'->>'id'<>f1::text OR app_private.can_write_workspace(ua,wa) THEN RAISE EXCEPTION 'Desk proof: expired Desk read/write split'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_identity_command;
 denied:=false;BEGIN PERFORM app_private.mhp_save_deal_file(ta,gen_random_uuid(),f2,2,'Expired write','{}','brrr',calc->'inputs',calc,'proof-v1');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: expired file update'; END IF;checks:=checks+1;
 v1:=app_private.mhp_submit_verdict(ta,verdict_cmd,answers);again:=app_private.mhp_submit_verdict(ta,verdict_cmd,answers);
 IF v1<>again THEN RAISE EXCEPTION 'Desk proof: verdict replay'; END IF;checks:=checks+1;
 denied:=false;BEGIN PERFORM app_private.mhp_submit_verdict(ta,gen_random_uuid(),answers);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: duplicate intake'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_owner;
 denied:=false;BEGIN UPDATE app.mhp_verdict_requests r SET answers=r.answers||'{"goals":"Changed"}'::jsonb WHERE id=v1;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: intake overwritten'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_identity_command;
 v2:=app_private.mhp_submit_verdict(tb,gen_random_uuid(),answers);
 SET LOCAL ROLE r72_owner;
 IF NOT EXISTS(SELECT 1 FROM app.mhp_verdict_requests WHERE id=v2 AND source='manual' AND purchase_id IS NULL) OR EXISTS(SELECT 1 FROM app.purchases WHERE account_id=ub) THEN RAISE EXCEPTION 'Desk proof: manual verdict invented purchase'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_web;
 denied:=false;BEGIN PERFORM app_private.mhp_verdict_queue(ta);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: member read owner queue'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_identity_command;
 IF NOT app_private.request_mhp_auth_token('office@propertypredator.com','magic',owner_auth,owner_token) THEN RAISE EXCEPTION 'Desk proof: owner token unavailable'; END IF;
 SELECT x.user_id,x.selected_workspace_id INTO owner_id,owner_ws FROM app_private.consume_mhp_auth_token(owner_auth,'magic',NULL,owner_token,owner_token,owner_token,NULL) x;
 SET LOCAL ROLE r72_web;
 value:=app_private.mhp_verdict_queue(owner_token);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(value->'requests') q WHERE q->>'id'=v1::text AND q->>'memberEmail'=emaila AND q->'answers'=answers) THEN RAISE EXCEPTION 'Desk proof: owner queue missing intake'; END IF;checks:=checks+1;
 value:=app_private.mhp_desk_snapshot(owner_token,NULL);
 IF value->'fileLimit'<>'null'::jsonb OR NOT(value->'access'->>'calculators')::boolean OR (value->'access'->>'readOnly')::boolean THEN RAISE EXCEPTION 'Desk proof: owner unrestricted test Desk'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_identity_command;
 PERFORM app_private.mhp_review_verdict(owner_token,review_cmd,v1,2,'Focus on one buy-to-let lane; discuss your assumptions at the next review.');
 PERFORM app_private.mhp_review_verdict(owner_token,review_cmd,v1,2,'Focus on one buy-to-let lane; discuss your assumptions at the next review.');
 SET LOCAL ROLE r72_web;
 value:=app_private.mhp_desk_snapshot(ta,NULL);
 IF value->'verdict'->>'status'<>'reviewed' OR value->'verdict'->>'response' IS NULL THEN RAISE EXCEPTION 'Desk proof: member verdict response'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_owner;
 IF (SELECT count(*) FROM app_private.mhp_deal_commands WHERE command_id=review_cmd)<>1 THEN RAISE EXCEPTION 'Desk proof: review audit replay'; END IF;checks:=checks+1;
 INSERT INTO app.entitlements(id,account_id,product_id,grants,starts_at,source,source_reference)
 SELECT course_id,ua,id,grants,stamp-interval '1 hour','manual','isolated-course-upgrade' FROM app.products WHERE id=course;
 SET LOCAL ROLE r72_web;
 value:=app_private.mhp_desk_snapshot(ta,NULL);
 IF (value->'access'->>'readOnly')::boolean OR value->'fileLimit'<>'null'::jsonb OR NOT app_private.can_write_workspace(ua,wa) THEN RAISE EXCEPTION 'Desk proof: course upgrade did not lift limits'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_identity_command;
 f4:=app_private.mhp_save_deal_file(ta,gen_random_uuid(),NULL,NULL,'Fourth after course','{}','brrr',calc->'inputs',calc,'proof-v1');
 SET LOCAL ROLE r72_owner;
 IF (SELECT count(*) FROM app.deal_files WHERE workspace_id=wa)<>4 THEN RAISE EXCEPTION 'Desk proof: course fourth file'; END IF;checks:=checks+1;
 UPDATE app.purchases SET status='refunded',refunded_at=clock_timestamp() WHERE id=purchase;
 SET LOCAL ROLE r72_mhp_commerce_definer;PERFORM app_private.mhp_refresh_entitlement(purchase);SET LOCAL ROLE r72_owner;
 SET LOCAL ROLE r72_web;
 value:=app_private.mhp_desk_snapshot(ta,NULL);
 IF (value->'access'->>'readOnly')::boolean THEN RAISE EXCEPTION 'Desk proof: refund revoked separate course'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_owner;
 UPDATE app.entitlements SET ends_at=clock_timestamp() WHERE id=course_id;
 SET LOCAL ROLE r72_web;
 value:=app_private.mhp_desk_snapshot(ta,NULL);
 IF NOT(value->'access'->>'readOnly')::boolean OR NOT(value->'access'->>'calculators')::boolean THEN RAISE EXCEPTION 'Desk proof: refund read-only grace'; END IF;checks:=checks+1;
 IF value->'verdict'->>'id'<>v1::text OR value->'verdict'->>'response' IS NULL OR (value->>'canSubmitVerdict')::boolean THEN RAISE EXCEPTION 'Desk proof: refunded verdict remains readable without new submission'; END IF;checks:=checks+1;
 SET LOCAL ROLE r72_owner;
 UPDATE app.entitlements SET starts_at=stamp-interval '40 days',ends_at=stamp-interval '8 days',read_only_until=stamp-interval '1 day',crm_write_ends_at=stamp-interval '10 days' WHERE purchase_id=purchase;
 SET LOCAL ROLE r72_web;
 denied:=false;BEGIN PERFORM app_private.mhp_desk_snapshot(ta,NULL);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'Desk proof: refund grace never ended'; END IF;checks:=checks+1;
 RAISE NOTICE 'MHP Deal Desk isolated assertions passed: %',checks;
END $proof$;
RESET ROLE;
